PREFIX rdfs: <rdfs:>
SELECT * WHERE {
  ?s rdfs:label "Perimeter_bot_ZN_2" .
}

PREFIX brick: <brick:>
PREFIX ref: <ref:>
PREFIX rdfs: <rdfs:>
SELECT ?cls ?lbl WHERE {
  ?s a ?cls .
  ?s rdfs:label "Perimeter_bot_ZN_2" .
  OPTIONAL { ?s rdfs:label ?lbl }
}

SELECT ?s ?lbl ?cls WHERE {
  ?s rdfs:label ?lbl .
  ?s a brick:Zone .
  FILTER (CONTAINS(?lbl, "Perimeter_bot_ZN_2"))
}

SELECT ?point ?cls ?lbl ?ts WHERE {
  ?point rdfs:label ?lbl .
  ?point a ?cls .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  FILTER(CONTAINS(?lbl,"Zone_F2_Z03") || CONTAINS(?lbl,"Perimeter_bot_ZN_2"))
}

PREFIX brick: <brick:>
SELECT ?point ?cls ?lbl WHERE {
  ?point rdfs:label ?lbl .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  FILTER(CONTAINS(?lbl,"ZN_2"))
}

SELECT ?point ?lbl WHERE {
  ?point a brick:Air_Temperature .
  OPTIONAL { ?point ref:hasTimeseriesId ?ts }
  ?point rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl,"Perimeter_bot_ZN_2"))
}

PREFIX brick: <brick:>
SELECT ?point ?cls ?lbl WHERE {
  ?point brick:hasLocation "http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z03" .
  ?point a ?cls .
  OPTIONAL { ?point rdfs:label ?lbl }
}

